# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TELLING YEARS, DATES AND PREPOSITIONS OF TIME (IN / ON)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Reading Years (Yılların Okunuşu)</text>\n  <text x="42" y="100" font-size="11.5" fill="#334155">• 1881 → eighteen eighty-one (18 - 81)</text>\n  <text x="42" y="124" font-size="11.5" fill="#334155">• 1938 → nineteen thirty-eight (19 - 38)</text>\n  <text x="42" y="148" font-size="11.5" fill="#334155">• 1900 → nineteen hundred</text>\n  <text x="42" y="172" font-size="11.5" fill="#334155">• 2000 → two thousand</text>\n  <text x="42" y="196" font-size="11.5" fill="#334155">• 2005 → two thousand (and) five</text>\n  <text x="42" y="220" font-size="11.5" fill="#334155">• 2015 → twenty fifteen / two thousand fifteen</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Dates &amp; Prepositions (IN vs. ON)</text>\n  <text x="378" y="100" font-size="11.5" font-weight="bold" fill="#166534">1. IN + Years / Months / Cities:</text>\n  <text x="388" y="120" font-size="11" fill="#334155">• She was born IN 1946 / IN September / IN London.</text>\n  <text x="378" y="148" font-size="11.5" font-weight="bold" fill="#166534">2. ON + Full Dates (Day + Month) / Days:</text>\n  <text x="388" y="168" font-size="11" fill="#334155">• He graduated ON 15th May, 1998.</text>\n  <text x="378" y="196" font-size="11.5" font-weight="bold" fill="#166534">3. Reading Full Dates (Ordinal Numbers):</text>\n  <text x="388" y="216" font-size="11" fill="#334155">• 10 November → the tenth of November</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">LIFE MILESTONES, ACHIEVEMENTS &amp; BIOGRAPHY VOCABULARY</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Early Life &amp; Education</text>\n  <text x="40" y="100" font-size="11.5" fill="#334155">• be born (was/were born)</text>\n  <text x="40" y="124" font-size="11.5" fill="#334155">• grow up → grew up (büyümek)</text>\n  <text x="40" y="148" font-size="11.5" fill="#334155">• begin school → began school</text>\n  <text x="40" y="172" font-size="11.5" fill="#334155">• graduate from university</text>\n  <text x="40" y="196" font-size="11.5" fill="#334155">• move to another city/country</text>\n  <text x="40" y="220" font-size="11" font-weight="bold" fill="#1e40af">to study physics / medicine</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Family &amp; Personal Life</text>\n  <text x="260" y="100" font-size="11.5" fill="#334155">• get engaged (nişanlanmak)</text>\n  <text x="260" y="124" font-size="11.5" fill="#334155">• get married to (evlenmek)</text>\n  <text x="260" y="148" font-size="11.5" fill="#334155">• raise children / kids</text>\n  <text x="260" y="172" font-size="11.5" fill="#334155">• live alone (yalnız yaşamak)</text>\n  <text x="260" y="196" font-size="11.5" fill="#334155">• own a house / company</text>\n  <text x="260" y="220" font-size="11.5" fill="#334155">• die → died (vefat etmek)</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="570" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Career &amp; Achievements</text>\n  <text x="480" y="100" font-size="11.5" fill="#334155">• brilliant / extraordinary</text>\n  <text x="480" y="124" font-size="11.5" fill="#334155">• win an award / a prize</text>\n  <text x="480" y="148" font-size="11.5" fill="#334155">• win the Nobel Prize</text>\n  <text x="480" y="172" font-size="11.5" fill="#334155">• discover (keşfetmek)</text>\n  <text x="480" y="196" font-size="11.5" fill="#334155">• invent / make an invention</text>\n  <text x="480" y="220" font-size="11.5" fill="#334155">• become a famous scientist</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">FAMOUS BIOGRAPHIES &amp; SPOTTING SPECIFIC INFORMATION</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Prof. Dr. Aziz Sancar</text>\n  <text x="38" y="98" font-size="11" fill="#334155">• Born: in Savur, Mardin in 1946.</text>\n  <text x="38" y="120" font-size="11" fill="#334155">• Education: Graduated from</text>\n  <text x="38" y="136" font-size="11" fill="#334155">  Istanbul University (Medicine).</text>\n  <text x="38" y="158" font-size="11" fill="#334155">• Moved to the USA to study</text>\n  <text x="38" y="174" font-size="11" fill="#334155">  molecular biology (DNA repair).</text>\n  <text x="38" y="198" font-size="11" font-weight="bold" fill="#1e40af">• Achievement: Won the Nobel</text>\n  <text x="38" y="214" font-size="11" font-weight="bold" fill="#1e40af">  Prize in Chemistry in 2015.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Marie Curie (1867–1934)</text>\n  <text x="258" y="98" font-size="11" fill="#334155">• Born: in Warsaw, Poland in 1867.</text>\n  <text x="258" y="120" font-size="11" fill="#334155">• Moved to Paris to study physics</text>\n  <text x="258" y="136" font-size="11" fill="#334155">  and mathematics at Sorbonne.</text>\n  <text x="258" y="158" font-size="11" fill="#334155">• Married Pierre Curie in 1895.</text>\n  <text x="258" y="180" font-size="11" font-weight="bold" fill="#166534">• Discovered radium &amp; polonium.</text>\n  <text x="258" y="202" font-size="11" font-weight="bold" fill="#166534">• First woman to win 2 Nobel</text>\n  <text x="258" y="218" font-size="11" font-weight="bold" fill="#166534">  Prizes (Physics &amp; Chemistry).</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Nikola Tesla &amp; İdil Biret</text>\n  <text x="478" y="98" font-size="11" fill="#334155">• Nikola Tesla (1856–1943):</text>\n  <text x="478" y="116" font-size="10.5" fill="#475569">  Brilliant inventor; worked on</text>\n  <text x="478" y="132" font-size="10.5" fill="#475569">  alternating current (AC) electricity;</text>\n  <text x="478" y="148" font-size="10.5" fill="#475569">  lived alone and had 300+ patents.</text>\n  <text x="478" y="174" font-size="11" fill="#334155">• İdil Biret (born in 1941):</text>\n  <text x="478" y="192" font-size="10.5" fill="#475569">  Turkish piano prodigy; went to</text>\n  <text x="478" y="208" font-size="10.5" fill="#475569">  Paris Conservatory at age 7;</text>\n  <text x="478" y="224" font-size="10.5" fill="#475569">  National Artist (Devlet Sanatçısı).</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
